import * as Schema from "effect/Schema";
import { GameLibraryPackId } from "./gameLibraryPackId.ts";

/** The style lock's file, at the game root beside BRIEF.md and ASSETS.md. */
export const GAME_STYLE_FILE = "STYLE.json";

/**
 * How a game's models are made: in three.js code, in Blender, or generated by the person's art
 * providers. The person picks it in game.json, never the harness; the free library is a separate
 * opt-in (GameManifest `library`).
 */
export const GameCharacterRoute = Schema.Literals(["code", "blender", "generated"]);
export type GameCharacterRoute = typeof GameCharacterRoute.Type;
/** game.json's `characters` as stored: "library" is the old default, read as code with the library on. */
export const GameStoredCharacterRoute = Schema.Literals([
  "code",
  "blender",
  "generated",
  "library",
]);
export type GameStoredCharacterRoute = typeof GameStoredCharacterRoute.Type;

/** Why a route cannot be chosen yet; a route missing here can be. The server refuses the rest. */
export const GAME_CHARACTER_ROUTE_UNAVAILABLE: Partial<Record<GameCharacterRoute, string>> = {};

const Hex = Schema.String.check(Schema.isPattern(/^#[0-9a-fA-F]{6}$/));

/** How the game is seen: it sets the views sprites render from. */
export const GameStyleView = Schema.Literals(["side", "top-down", "isometric", "perspective"]);
export type GameStyleView = typeof GameStyleView.Type;

/**
 * The colour each kind of made thing takes when STYLE.json names none: the roles the Blender kit's
 * world helpers and the code route's shell/model.js colour by, so one lock gives one family.
 * A lock may name more of its own.
 */
export const GAME_STYLE_ROLES = {
  bark: "#6b4a32",
  leaf: "#4f8a3c",
  leaf2: "#6fa84a",
  stone: "#8a8780",
  stone2: "#6f6c66",
  moss: "#5f7a3a",
  grass: "#6a9a48",
  grass2: "#8aae52",
  soil: "#7a5c3c",
  path: "#b89a6a",
  sand: "#d8c690",
  water: "#4a86a8",
  wall: "#d9cdb4",
  roof: "#a2523a",
  trim: "#5a4030",
  floor: "#9a7650",
  door: "#6a4a2e",
  glass: "#9fc4d6",
  metal: "#8a8f96",
  cloth: "#b5483a",
} as const;

/** How made things are shaped: read by the kit's world helpers and shell/model.js. */
export const GameStyleShape = Schema.Struct({
  /** faceted: flat faces and hard edges; soft: smooth shading and rounder forms. */
  edges: Schema.optionalKey(Schema.Literals(["faceted", "soft"])),
  /** Metres a built thing's edges are rounded by. */
  bevel: Schema.optionalKey(Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 0.2 }))),
  /** 0 true to life, 1 chunky: thick trunks, big crowns and roofs, squat walls. */
  chunky: Schema.optionalKey(Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 1 }))),
  /** 0 bare forms, 1 every beam, sill and tuft. */
  detail: Schema.optionalKey(Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 1 }))),
});
export type GameStyleShape = typeof GameStyleShape.Type;

/** flat: plain colours; painted: soft hand-painted surfaces; real: surfaces with full grain and relief. */
export const GameStyleFinish = Schema.Literals(["flat", "painted", "real"]);
export type GameStyleFinish = typeof GameStyleFinish.Type;

const Role = Schema.String.check(Schema.isPattern(/^[a-z][a-z0-9_]{0,23}$/));
/** The made surface a role wears (kurambit.surface): its kind, pattern, tile size in metres and wear. */
export const GameStyleSurface = Schema.Struct({
  kind: Schema.String.check(Schema.isMaxLength(24)),
  pattern: Schema.optionalKey(Schema.String.check(Schema.isMaxLength(24))),
  metres: Schema.optionalKey(Schema.Number.check(Schema.isBetween({ minimum: 0.05, maximum: 50 }))),
  wear: Schema.optionalKey(Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 1 }))),
});

/** What of a lock made things are built from: served to the game's code and read by the Blender kit. */
const lookFields = {
  /** A colour per role (GAME_STYLE_ROLES and the game's own): what made things are coloured by. */
  roles: Schema.optionalKey(Schema.Record(Role, Hex)),
  shape: Schema.optionalKey(GameStyleShape),
  /** Omitted: flat under a hex palette, real without one. */
  finish: Schema.optionalKey(GameStyleFinish),
  /** The surface set: the made surface each role wears where the finish is not flat. */
  surfaces: Schema.optionalKey(Schema.Record(Role, GameStyleSurface)),
};

/**
 * STYLE.json: the look a game records. game_assets op lock writes it for what the game makes
 * (palette by role, shape, finish, surfaces) and op add from a library family (GameStyleLock);
 * the person may edit it, and the art tools read it on every call to fill their defaults; none
 * refuses an asset for falling outside it.
 */
export const GameStyle = Schema.Struct({
  version: Schema.Literal(1),
  /** A style family from the library (game_assets op search lists them). */
  family: Schema.optionalKey(Schema.String.check(Schema.isMaxLength(64))),
  /** pixel: sprites are quantised to the palette at the tile's pixel scale; smooth: drawn at size. */
  mode: Schema.Literals(["pixel", "smooth"]),
  /** Source pixels per tile, for pixel mode. */
  tile: Schema.optionalKey(Schema.Int.check(Schema.isBetween({ minimum: 4, maximum: 128 }))),
  /** pixel: a pack id or a game-relative PNG or folder; smooth: also a hex list, the 3D style pass's colours. */
  palette: Schema.optionalKey(
    Schema.Union([
      Schema.String.check(Schema.isMinLength(1), Schema.isMaxLength(300)),
      Schema.Array(Hex).check(Schema.isMinLength(2), Schema.isMaxLength(64)),
    ]),
  ),
  /** The 3D style pass's shading: gradient strength of each swatch, roughness, emissive strength of glow colours, baked depth. */
  shading: Schema.optionalKey(
    Schema.Struct({
      gradient: Schema.optionalKey(
        Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 0.5 })),
      ),
      roughness: Schema.optionalKey(
        Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 1 })),
      ),
      glow: Schema.optionalKey(Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 20 }))),
      /** How strongly a made model is shaded into its vertex colours (creases, a gradient, a darker underside); 0 leaves it flat. */
      depth: Schema.optionalKey(Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 1 }))),
      /** A made model's surface: "faceted" thins it to clean planes, shaded flat; "smooth" (the default) keeps it round. */
      finish: Schema.optionalKey(Schema.Literals(["smooth", "faceted"])),
    }),
  ),
  /** Metres: a made character is scaled to this standing height. */
  scale: Schema.optionalKey(
    Schema.Struct({
      character: Schema.optionalKey(
        Schema.Number.check(Schema.isBetween({ minimum: 0.1, maximum: 20 })),
      ),
    }),
  ),
  /** Export budgets: triangles per character and per prop, and the largest texture side in px. */
  budget: Schema.optionalKey(
    Schema.Struct({
      character: Schema.optionalKey(
        Schema.Int.check(Schema.isBetween({ minimum: 500, maximum: 200_000 })),
      ),
      prop: Schema.optionalKey(
        Schema.Int.check(Schema.isBetween({ minimum: 50, maximum: 100_000 })),
      ),
      texture: Schema.optionalKey(
        Schema.Int.check(Schema.isBetween({ minimum: 16, maximum: 4096 })),
      ),
    }),
  ),
  /**
   * The game-relative image the whole look answers to (the person's picked key art, usually
   * art/key-art.png): every image generation passes it as a reference (a 3D one takes only its
   * subject's picture), and the palette is read from it.
   */
  anchor: Schema.optionalKey(Schema.String.check(Schema.isMinLength(1), Schema.isMaxLength(300))),
  /** A 1 px outline on rendered sprites: true for the palette's darkest colour, or #rrggbb. */
  outline: Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.String])),
  view: GameStyleView,
  /**
   * The skeleton made characters are conformed to, so every clip fits them; a pack the lock
   * lists may still bring characters on its own rig. Omitted when none is rigged.
   */
  rig: Schema.optionalKey(Schema.String.check(Schema.isMaxLength(64))),
  ...lookFields,
  /**
   * The library packs the game's visuals come from; a pack-id palette is allowed without listing
   * it. A game that makes everything lists none.
   */
  packs: Schema.optionalKey(Schema.Array(GameLibraryPackId).check(Schema.isMaxLength(32))),
  audio: Schema.optionalKey(
    Schema.Struct({
      /** The library packs the game's sounds and music come from; omitted, sound is not locked. */
      packs: Schema.optionalKey(Schema.Array(GameLibraryPackId).check(Schema.isMaxLength(16))),
      /** Integrated loudness of the music, in LUFS. Default -23. */
      musicLufs: Schema.optionalKey(
        Schema.Number.check(Schema.isBetween({ minimum: -40, maximum: -6 })),
      ),
      /** True-peak ceiling of the effects, in dBTP. Default -1. */
      sfxPeakDbtp: Schema.optionalKey(
        Schema.Number.check(Schema.isBetween({ minimum: -12, maximum: 0 })),
      ),
    }),
  ),
}).check(
  Schema.makeFilter((style) => {
    const issues: Array<Schema.FilterIssue> = [];
    if (style.mode === "pixel" && style.tile === undefined)
      issues.push({ path: ["tile"], issue: "pixel mode needs tile: source pixels per tile" });
    if (style.mode === "pixel" && style.palette === undefined)
      issues.push({ path: ["palette"], issue: "pixel mode needs palette: a pack id or a PNG" });
    if (style.mode === "pixel" && Array.isArray(style.palette))
      issues.push({
        path: ["palette"],
        issue: "pixel mode reads its palette from a pack id or a PNG",
      });
    if (typeof style.outline === "string" && !/^#[0-9a-fA-F]{6}$/.test(style.outline))
      issues.push({ path: ["outline"], issue: "outline is true, false or #rrggbb" });
    return issues;
  }),
);
export type GameStyle = typeof GameStyle.Type;

/** A choice of look: game_assets op add derives STYLE.json's family fields from it. */
export const GameStyleLock = Schema.Struct({
  /** A style family from the library (game_assets op search lists them). */
  family: Schema.String.check(Schema.isMinLength(1), Schema.isMaxLength(64)),
  view: GameStyleView,
});
export type GameStyleLock = typeof GameStyleLock.Type;

/**
 * game_assets op lock: the look of what the game makes, written into STYLE.json. What it leaves
 * out keeps its value there; `roles` it does not name come from the palette.
 */
export const GameStyleLockInput = Schema.Struct({
  view: Schema.optionalKey(GameStyleView),
  /** Hex colours, or a PNG in the game (the key art, the person's reference) to read them from. */
  palette: Schema.optionalKey(
    Schema.Union([
      Schema.Array(Hex).check(Schema.isMinLength(2), Schema.isMaxLength(64)),
      Schema.String.check(Schema.isMinLength(1), Schema.isMaxLength(300)),
    ]),
  ),
  ...lookFields,
});
export type GameStyleLockInput = typeof GameStyleLockInput.Type;

/** The part of a lock the game's own code reads, served beside the runtime (gameWebServer). */
export const GameLook = Schema.Struct({
  view: Schema.optionalKey(GameStyleView),
  palette: Schema.optionalKey(Schema.Array(Hex)),
  ...lookFields,
});
export type GameLook = typeof GameLook.Type;

export const GAME_STYLE_DEFAULT_MUSIC_LUFS = -23;
export const GAME_STYLE_DEFAULT_SFX_PEAK_DBTP = -1;
/**
 * How a new game's models are made unless the person picks otherwise: Blender, where heroes and
 * creatures are modelled and the rest is built in code (the AQ bake-off: Blender's characters beat
 * code's and the library's). A game.json with no route stays code (gameModelChoice).
 */
export const GAME_STYLE_DEFAULT_CHARACTERS: GameCharacterRoute = "blender";
/** Whether a new game may take models from the free library; the person turns it on. */
export const GAME_STYLE_DEFAULT_LIBRARY = false;

/**
 * The person's model choice a manifest holds. A game.json from before the library became opt-in
 * has no `library` key: its library stays on, as it was, and its old "library" route is code.
 */
export const gameModelChoice = (manifest: {
  readonly characters?: GameStoredCharacterRoute | undefined;
  readonly library?: boolean | undefined;
}): { readonly route: GameCharacterRoute; readonly library: boolean } => ({
  // No route at all is how the code route is written (scaffold.ts), whatever new games default to.
  route:
    manifest.characters === undefined || manifest.characters === "library"
      ? "code"
      : manifest.characters,
  library: manifest.library ?? true,
});
/**
 * What a model may weigh when STYLE.json names no budget. A default has to hold what the kit
 * itself makes at full quality (an MPFB2 body is 26,756 triangles before its clothes, hair and
 * prop), or it reads as an order to cut detail; a game with a crowd sets its own lower.
 */
export const GAME_STYLE_DEFAULT_BUDGET = {
  character: 50_000,
  prop: 15_000,
  texture: 1024,
} as const;
